// \u4E5F\u53EF\u4EE5\u76F4\u63A5\u4F7F\u7528\u7EC4\u4EF6\u7684getFormattedRules\u65B9\u6CD5\u83B7\u53D6\u683C\u5F0F\u5316\u540E\u7684\u89C4\u5219\u8FDB\u884C\u8BC4\u4F30
